```go
type MinHeap [][3]int

func (h MinHeap) Len() int            { return len(h) }
func (h MinHeap) Less(i, j int) bool  { return h[i][0] < h[j][0] }
func (h MinHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *MinHeap) Push(x interface{}) { *h = append(*h, x.([3]int)) }
func (h *MinHeap) Pop() interface{} {
    old := *h
    n := len(old)
    x := old[n-1]
    *h = old[:n-1]
    return x
}

func findCheapestPrice(n int, flights [][]int, src int, dst int, k int) int {
    INF := 1000000000
    adj := make([][]struct{ to, cost int }, n)
    dist := make([][]int, n)
    for i := range dist {
        dist[i] = make([]int, k+5)
        for j := range dist[i] {
            dist[i][j] = INF
        }
    }
    for _, flight := range flights {
        from, to, cost := flight[0], flight[1], flight[2]
        adj[from] = append(adj[from], struct{ to, cost int }{to, cost})
    }
    dist[src][0] = 0
    minHeap := &MinHeap{}
    heap.Init(minHeap)
    heap.Push(minHeap, [3]int{0, src, -1})
    for minHeap.Len() > 0 {
        value := heap.Pop(minHeap).([3]int)
        cst, node, stops := value[0], value[1], value[2]
        if node == dst {
            return cst
        }
        if stops == k || dist[node][stops+1] < cst {
            continue
        }
        for _, nei := range adj[node] {
            nextCst := cst + nei.cost
            nextStops := stops + 1
            if dist[nei.to][nextStops+1] > nextCst {
                dist[nei.to][nextStops+1] = nextCst
                heap.Push(minHeap, [3]int{nextCst, nei.to, nextStops})
            }
        }
    }
    return -1
}
